  let eventLookups = 0;

  before(async () => {
    srv = await startTestServer();
    for (let i = 0; i < 5000; i++) {
      srv.store.addShipment(
        { trackingNumber: `T${i}`, carrier: 'DHL', serviceLevel: 'standard', recipient },
        new Date(Date.UTC(2026, 10, 1) + i * 60_000),
      );
