    const original = srv.store.eventsFor.bind(srv.store);
    srv.store.eventsFor = (id: string) => {
      eventLookups++;
      return original(id);
    };
  });

  after(async () => {
    await srv.close();
  });

  it('computes the eta only for the returned page', async () => {
    eventLookups = 0;
    const res = await api(srv.url, 'GET', '/shipments');
